    "description": "市场监管总局今天（22日）就《企业境外反垄断合规指引（修订草案征求意见稿）》公开征求意见，进一步引导我国企业增强海外反垄断合规意识，防范相关法律风险。意见反馈截止日期为2026年9月29日。为帮助企业了解域外最新反垄断监管趋势，本次修订总结并新增了反垄断立法和执法变化，如在垄断协议、滥用市场地位、经营者集中等专章中嵌入境外反垄断执法机构对数字经济的关注。明确了欧盟、美国、德国等司法辖区最新经营者集中申报标准等，提示企业关注外商投资安全审…",
    "content": "市场监管总局今天（22日）就《企业境外反垄断合规指引（修订草案征求意见稿）》公开征求意见，进一步引导我国企业增强海外反垄断合规意识，防范相关法律风险。意见反馈截止日期为2026年9月29日。为帮助企业了解域外最新反垄断监管趋势，本次修订总结并新增了反垄断立法和执法变化，如在垄断协议、滥用市场地位、经营者集中等专章中嵌入境外反垄断执法机构对数字经济的关注。明确了欧盟、美国、德国等司法辖区最新经营者集中申报标准等，提示企业关注外商投资安全审查和外国补贴审查制度。针对域外反垄断诉讼和调查高发的趋势，在行政罚款及刑事责任外…"
