    "content": "9月22日，中国驻札幌总领馆发文提醒中国公民注意户外活动安全。 提醒指出，近日日本气象部门已将北海道大雪山系十胜岳的火山喷发警戒级别提升至3级“限制入山”，呼吁人员不要进入火山范围，警惕火山喷发可能带来的落石、有毒气体等安全风险。 同时，北海道及东北三县各地近期多次报告发现棕熊的活动踪迹，各地政府提醒秋季棕熊觅食活跃，进山及近郊活动应保持警惕，避免单独行动，加强安全防范。 中国驻札幌总领馆郑重提醒领区中国公民务必高度重视户外活动安全，密切关注相关部门发布的各类预警信息，提高安全意识，避免前往危险区域。 如遇突发情况…"
