    "pub_date": "2026-09-22 17:56:46",
    "author": "",
    "description": "昔日黄沙蔽日，今朝满目青翠！走进乌审旗毛乌素沙地生命共同体科研中心，新旧对比的生态图景扑面而来。鲜活的沙生植物、生动的治沙人物塑像、详实的沙盘数据、动态的生态大数据屏幕，清晰记录着毛乌素沙地从荒漠戈壁到绿洲沃野的惊艳蜕变。9月21日，“铸牢共同体 中华一家亲”主题宣传活动采访团走进乌审召镇，实地探寻这片土地逆袭变绿的秘密。",
    "content": "昔日黄沙蔽日，今朝满目青翠！走进乌审旗毛乌素沙地生命共同体科研中心，新旧对比的生态图景扑面而来。鲜活的沙生植物、生动的治沙人物塑像、详实的沙盘数据、动态的生态大数据屏幕，清晰记录着毛乌素沙地从荒漠戈壁到绿洲沃野的惊艳蜕变。9月21日，“铸牢共同体 中华一家亲”主题宣传活动采访团走进乌审召镇，实地探寻这片土地逆袭变绿的秘密。"
