    "description": "36氪获悉，*ST康佳A公告，公司拟以股东会决议方式主动终止A、B股上市并转入退市板块，该事项已经2026年第二次临时股东会审议通过。公司股票自2026年9月4日开市起连续停牌，将进入现金选择权派发、行权申报、清算交收阶段，不再交易。A股现金选择权行权价2.48元/股，B股0.73港币/股，申报期为2026年9月30日至10月13日的交易日。",
