    "content": "今年以来，熊猫债券发行规模已超去年全年，吸引力不断增强。 权威数据显示，今年以来，截至9月17日，熊猫债券发行规模超2400亿元，发行只数为135只，与去年同期相比，分别增长81%、65%。 熊猫债是境外机构在中国境内发行的、以人民币计价的还本付息的债券，是拓宽人民币跨境融资渠道、助力人民币国际化进程的重要工具。 从发行人结构来看，今年以来，纯外资发行占比显著提升，主权发行人成为重要增量，斯洛文尼亚、巴基斯坦、哈萨克斯坦、印度尼西亚首次成功发行熊猫债。此外，巴西财政部已向中方递交了熊猫债发行申请函，有望成为首个注册…"
