    "description": "新华网兰州9月22日电 日前，中央对甘肃省委主要负责同志职务进行了调整。吴晓军同志任甘肃省委委员、常委、书记，胡昌升同志不再担任甘肃省委书记、常委、委员职务。 9月22日，甘肃省召开领导干部会议，中央组织部副部长齐家滨同志在会上宣布了中央决定，称这次调整是中央从大局出发，根据工作需要和甘肃省领导班子建设实际，经过通盘考虑、慎重研究决定的。 吴晓军同志1966年1月出生，江西泰和人。曾任江西省工业和信息化委员会主任，省发展改革委主任，20…",
    "content": "新华网兰州9月22日电 日前，中央对甘肃省委主要负责同志职务进行了调整。吴晓军同志任甘肃省委委员、常委、书记，胡昌升同志不再担任甘肃省委书记、常委、委员职务。 9月22日，甘肃省召开领导干部会议，中央组织部副部长齐家滨同志在会上宣布了中央决定，称这次调整是中央从大局出发，根据工作需要和甘肃省领导班子建设实际，经过通盘考虑、慎重研究决定的。 吴晓军同志1966年1月出生，江西泰和人。曾任江西省工业和信息化委员会主任，省发展改革委主任，2017年3月后任副省长，省委常委、副省长，省委常委、南昌市委书记，青海省委副书记，…"
