    "content": "背景 我在做文档翻译网站 O.Translator （国外版） 和 商译 AI （国内版） 的时候，需要在浏览器支持 DOCX 、PDF 、PPTX 等不同文件的渲染预览。 项目初期，大部分文件类型预览都是使用开源库，对于 DOCX 文档，我选择了 VolodymyrBaydalka/docxjs 。 这个库做基本展示没问题，但大文件渲染（ 20M 以上），会卡，有时候甚至让浏览器崩溃。初期，我只能在外层加门禁限制，比如 XML 超出 500 个或者文件超过 20M ，就不在网页渲染预览，让用户下载。 性能是最大的…"
