    "content": "新华社首尔9月22日电（记者陈怡 孙一然）据韩联社报道，韩国首尔高等法院22日就前总统尹锡悦妻子金建希涉嫌“卖官鬻爵”一案作出二审判决，将一审的有期徒刑7年改判为有期徒刑5年，没收受贿财物，并追缴2440万韩元（约合12万元人民币）。 二审中，首尔高等法院针对金建希多项指控进行审理，其中两项指控因“无法证明存在人事请托目的”由一审有罪改判无罪，其余指控维持一审有罪认定。 “金建希特检组”5月15日就此案请求法院判处金建希有期徒刑7年6个月，并追缴非法所得。特检组指出，相关犯罪是指被告人作为总统配偶，将总统的各种权力…"
