    "content": "新华社科威特城9月22日电（记者尹炣）萨那消息：据也门胡塞武装控制的马西拉电视台22日报道，沙特阿拉伯战机当天凌晨对也门西南部塔伊兹省的红海港口城市穆哈发动空袭，造成6人死亡、8人受伤。 报道称，“沙特战机”当天对穆哈“一座民宅”发动3次空袭。6名死者中有2名儿童和1名妇女。马西拉电视台还播放了死伤者相关画面。 沙特方面暂未就此作出回应。 也门政府军和胡塞武装本月10日分别证实，胡塞武装当天攻占红海战略要地穆哈。近期，也门胡塞武装与支持也门政府军的沙特之间冲突持续升级，双方相互发动导弹、无人机袭击。"
