    "link": "https://www.chinanews.com.cn/gn/2026/09-22/10701498.shtml",
    "pub_date": "2026-09-22 15:42:07",
    "author": "",
    "description": "中新网9月22日电 据国家卫健委网站消息，根据《食品安全法》规定，国家卫生健康委、市场监管总局联合印发2026年第6号公告，发布50项新食品安全国家标准和修改单。新发布标准以防风险、保健康、促发展为导向，细化食品安全全链条管控要求，既是消费者健康权益的重要保障，也是监管执法的“硬标尺”，更是企业合规生产的重要依据。",
